const source = $json.body ?? $json;
const schemaVersion = source.schema_version ?? '1.0';
const provider = source.provider ?? 'test';
const providerMessageId = source.provider_message_id ?? source.message_id;
const contactId = source.external_contact_id ?? source.contact_id;
const text = typeof source.text === 'string' ? source.text.trim() : '';
const phone = String(source.phone_e164 ?? '+51999000001');
const channel = source.channel_account_external_id ?? 'odonto-smart-lab';
if (schemaVersion !== '1.0' || provider !== 'test') throw new Error('WF-01 accepts schema_version=1.0 and provider=test only.');
if (!providerMessageId || String(providerMessageId).length > 255 || !contactId || String(contactId).length > 255 || !text || text.length > 16000) throw new Error('WF-01 payload is missing a bounded message or contact.');
if (!/^\+[1-9][0-9]{7,14}$/.test(phone) || typeof channel !== 'string' || !channel.trim() || channel.length > 128) throw new Error('WF-01 contact or channel identity is invalid.');
return { json: {
  schema_version: '1.0',
  provider: 'test',
  channel_account_external_id: channel,
  provider_message_id: String(providerMessageId),
  external_contact_id: String(contactId),
  phone_e164: phone,
  message_type: 'text',
  text,
  occurred_at: source.occurred_at ?? new Date().toISOString(),
  request_id: crypto.randomUUID(),
  inbound_idempotency_key: crypto.randomUUID()
} };

const state = $getWorkflowStaticData('global');
const key = [
  $json.provider,
  $json.channel_account_external_id,
  $json.external_contact_id
].join(':');
state.inboundBuffers ??= {};
const current = state.inboundBuffers[key] ?? { events: [], dueAt: 0 };
if (current.events.length >= 8) throw new Error('WF-01 debounce buffer is full; retry transport later.');
current.events.push($json);
current.dueAt = Date.now() + 250;
state.inboundBuffers[key] = current;
return { json: { ...$json, debounce_key: key, debounce_due_at: new Date(current.dueAt).toISOString() } };

const state = $getWorkflowStaticData('global');
const key = $input.first().json.debounce_key;
const pending = state.inboundBuffers?.[key];
if (!pending || pending.dueAt > Date.now()) return [];
delete state.inboundBuffers[key];
return pending.events.map(event => ({ json: event }));
